// Old film: the room as a worn black-and-white print, after Tscherkassky's Outer Space. Hard
// silver contrast, a second exposure lying over the first, the print weaving in the gate, grain,
// scratches, dust and the projector's flicker at 24 frames a second. The kick flares the lamp
// and burns the second exposure in. Every change from one frame to the next stays under the
// flash limiter's step. param[0] contrast, param[1] wear, param[2] ghost.
vec3 Y = vec3(0.299, 0.587, 0.114);
float aspect = resolution.x / resolution.y;
float f = floor(time * 24.0);

// Gate weave: the print wanders a little in the gate, smoothly, so edges never jump.
vec2 weave = vec2(valueNoise(vec2(time * 3.0, 1.3)), valueNoise(vec2(time * 3.0, 7.9))) - 0.5;
vec2 p = uv + weave * vec2(0.0025, 0.0035) * strength;

// Two exposures on one print: the second drifts slowly sideways and down.
float drift = 0.5 + 0.5 * sin(time * 0.6);
vec2 go = vec2((0.02 + 0.06 * drift) * (0.4 + param[2]), 0.015 * sin(time * 0.37));
vec3 first = source(p);
vec3 second = source(clamp(p + go, 0.0, 1.0));

// Silver contrast on each exposure: crushed blacks, burnt highs.
float k = mix(1.1, 2.6, param[0]);
float l = clamp((dot(first, Y) - 0.45) * k + 0.5, 0.0, 1.0);
l = l * l * (3.0 - 2.0 * l);
float l2 = clamp((dot(second, Y) - 0.45) * k + 0.5, 0.0, 1.0);
l2 = l2 * l2 * (3.0 - 2.0 * l2) * 0.85;
// The kick burns the second exposure in.
l = mix(l, max(l, l2), clamp(param[2] * 0.8 + 0.15 * audio.beat, 0.0, 1.0));

// Uneven exposure: slow blotches of light and dark, as a hand-printed copy has.
float blotch = valueNoise(uv * vec2(aspect, 1.0) * 2.2 + vec2(time * 0.21, -time * 0.13));
l *= 1.0 + (blotch - 0.5) * (0.2 + 0.35 * param[1]);

// The projector: a flicker per frame, a flare on the kick, a hot centre and dark corners.
l *= 1.0 + (hash(vec2(f, 9.1)) - 0.5) * (0.03 + 0.04 * param[1]) + 0.06 * audio.beat;
l *= 1.0 - 0.5 * smoothstep(0.3, 1.0, length((uv - 0.5) * vec2(aspect, 1.0)));

// Scratches: thin vertical lines that live a few frames, white (emulsion) or dark (base).
float sc = 0.0;
for (int i = 0; i < 3; i++) {
  float fi = float(i);
  float life = floor(time * (2.0 + fi * 1.3));
  float on = step(1.0 - 0.7 * param[1], hash(vec2(life, fi * 3.1 + 0.5)));
  float x = hash(vec2(life, fi * 7.7 + 1.0)) + (hash(vec2(f, fi + 4.0)) - 0.5) * 0.002;
  float d = abs(uv.x - x) * resolution.x;
  float sgn = hash(vec2(life, fi + 20.0)) > 0.4 ? 1.0 : -1.0;
  sc += on * sgn * (1.0 - smoothstep(0.5, 2.0, d));
}
l += clamp(sc, -1.0, 1.0) * 0.13;

// Dust: dark specks, new every frame.
vec2 g = uv * vec2(aspect, 1.0) * 70.0;
vec2 cell = floor(g);
float pick = hash(cell + vec2(f * 0.731, f * 1.37));
vec2 spot = vec2(hash(cell + f + 3.1), hash(cell + f + 8.4)) * 0.6 + 0.2;
float dust = step(1.0 - 0.006 * param[1], pick) * (1.0 - smoothstep(0.1, 0.3, length(fract(g) - spot)));
l -= dust * 0.14;

// Grain: clumps a little bigger than a pixel, strongest in the mids; the hi-hats roughen it.
float grain = hash(floor(uv * resolution / 1.5) + vec2(f * 1.31, f * 0.77)) - 0.5;
l += grain * (0.05 + 0.05 * param[1] + 0.04 * audio.high) * (0.4 + 2.4 * l * (1.0 - l));
l = clamp(l, 0.0, 1.0);

// Print the silver: black, dark silver, silver, paper white, in straight steps.
vec3 tone = mix(palette[0], palette[1], clamp(l / 0.3, 0.0, 1.0));
tone = mix(tone, palette[2], clamp((l - 0.3) / 0.4, 0.0, 1.0));
tone = mix(tone, palette[3], clamp((l - 0.7) / 0.3, 0.0, 1.0));
return mix(first, tone, strength);

// Film run: three layers of upright 35 mm film slide sideways through the gate, right to left,
// over the picture, as in Outer Space: the light of the room goes through them. Each layer is a
// band of the music, at its own speed. Bass: wide, slow, heavy film carrying the room in its
// frames; the kick makes it shudder. Mids: faster film carrying the last frame, a print of a
// print. Highs: narrow, fastest film fluttering with the hats. Each layer shows more, and its
// soundtrack wave swings wider, with its band. All of it burnt, scratched and smeared by speed.
// param[0] film, param[1] speed, param[2] damage, param[3] smear.
vec3 Y = vec3(0.299, 0.587, 0.114);
float aspect = resolution.x / resolution.y;
vec3 under = source(uv);
float l = dot(under, Y);
float paper = 0.97;
float pace = mix(0.45, 1.7, param[1]);
float bands[3] = float[3](audio.low, audio.mid, audio.high);
float widths[3] = float[3](1.5, 1.05, 0.65);
float gaps[3] = float[3](0.25, 0.35, 0.5);
float speeds[3] = float[3](0.9, 1.7, 3.2);
float covAll = 0.0;
float travel0 = 0.0;
for (int i = 0; i < 3; i++) {
  float fi = float(i);
  float band = bands[i];
  float W = widths[i];
  float P = W + gaps[i] * W;
  float v = speeds[i] * pace;

  // Where the film is: steady speed, a stutter as it catches in the gate, and on the kick a
  // shudder: the heavy film is thrown on and caught back as the beat falls (zero at the onset
  // and at rest, so the kick never makes the film jump).
  float stut = 0.12 * valueNoise(vec2(time * 3.0, fi * 5.0));
  float lurch = i == 0 ? 0.3 * 4.0 * audio.beat * (1.0 - audio.beat) : 0.0;
  float pos = v * time + stut + lurch + fi * 3.7;
  // The blur along the run: three frames' travel and the stutter's, never less than a hole's
  // width, and the lurch: no edge moves further in a frame than the flash limiter allows.
  float blur = max((v + 0.6) / 20.0, 0.06) + lurch;
  if (i == 0) travel0 = v / 60.0;

  // The film leans a little and crawls along its own length.
  float tilt = (valueNoise(vec2(time * 0.07, fi * 9.0 + 1.0)) - 0.5) * 0.3;
  vec2 q = (uv - 0.5) * vec2(aspect, 1.0);
  vec2 r = vec2(cos(tilt) * q.x - sin(tilt) * q.y, sin(tilt) * q.x + cos(tilt) * q.y);
  float pitch = 0.1 + 0.05 * W;
  float yy = r.y + time * (fi - 1.0) * 0.07;

  // Blurred along the run: six taps over the blur, each one the whole strip.
  float cov = 0.0;
  float white = 0.0;
  float pic = 0.0;
  for (int j = 0; j < 6; j++) {
    float s = (r.x + pos + (float(j) / 5.0 - 0.5) * blur) / P;
    float n = floor(s);
    float u = fract(s) * P / W;
    // Torn edges.
    float e = 0.02 * valueNoise(vec2(yy * 14.0, n * 3.3 + fi));
    float inFilm = step(e, u) * step(u, 1.0 - e) * step(0.35, hash(vec2(n, fi * 3.0 + 0.5)));
    // Perforations: a column at each edge, soft rounded holes where the light comes through.
    float cx = u < 0.5 ? 0.06 / W : 1.0 - 0.06 / W;
    vec2 hp = vec2((u - cx) * W, (fract(yy / pitch + n * 0.37) - 0.5) * pitch);
    vec2 hs = vec2(0.035, 0.3 * pitch);
    float rr = 0.35 * hs.y;
    float hd = length(max(abs(hp) - hs + rr, 0.0)) - rr;
    float perf = 1.0 - smoothstep(-0.006, 0.006, hd);
    // The optical soundtrack: a jagged wave cutting burnt-clear film from the picture,
    // swinging with this layer's band of the music.
    float tri = abs(fract(yy * 3.5 + n * 0.61) - 0.5) * 2.0;
    tri = 0.5 + (tri - 0.5) * (0.25 + 0.75 * valueNoise(vec2(yy * 3.5, n * 2.9 + fi)));
    float amp = 0.3 + 0.45 * band;
    float edge = (0.32 + 0.16 * amp * (tri - 0.5) * 2.0) / W;
    float track = step(0.12 / W, u) * step(u, edge);
    float inPic = step(edge, u) * step(u, 1.0 - 0.12 / W);
    cov += inFilm;
    white += inFilm * max(perf, track);
    pic += inFilm * inPic;
  }
  cov /= 6.0;
  white /= 6.0;
  pic /= 6.0;
  covAll = max(covAll, cov);

  // How much of this layer shows: the film slider and the layer's band; the hats flutter the top layer.
  float a = param[0] * (0.55 + 0.25 * band);
  if (i == 2) a *= 0.75 + 0.25 * sin(time * 50.0) * band;

  // The film's own frames: the room, sliding with the film, frames out of register, some lost.
  float sc = (r.x + pos) / P;
  float sn = floor(sc);
  float fy = yy / (pitch * 4.0) + hash(vec2(sn, fi)) * 4.0;
  float fr = floor(fy);
  float filmL = 0.0;
  if (pic > 0.01 && i < 2) {
    // Three taps over the blur. The heavy film carries the room itself; the middle one the last
    // frame, so it carries the other films too, a print of a print.
    vec2 cp = uv + vec2((pos - lurch) / aspect, (hash(vec2(fr, sn + fi)) - 0.5) * 0.08);
    for (int k = 0; k < 3; k++) {
      vec2 tp = fract(cp + vec2((float(k) - 1.0) * 0.4 * blur / aspect, 0.0));
      // Its own contrast per tap, before they are averaged: the blur stays a blur.
      filmL += smoothstep(0.15, 0.85, dot(i == 0 ? source(tp) : lastFrame(tp), Y)) / 3.0;
    }
    if (hash(vec2(sn, fi + 7.0)) > 0.6) filmL = 1.0 - filmL;
    float lost = hash(vec2(fr, sn * 1.7 + fi));
    filmL = lost > 1.0 - 0.15 * param[2] ? 0.95 : (lost < 0.06 * param[2] ? 0.05 : filmL);
    // Frame lines: dark on both sides, so the next frame's picture never meets this one's.
    filmL *= smoothstep(0.0, 0.05, fract(fy)) * smoothstep(0.0, 0.05, 1.0 - fract(fy));
  }

  // Damage on the film, moving with it: burnt blotches and long scratches along the run.
  vec2 dp = vec2((r.x + pos) * 0.7, yy * 2.2 + fi * 11.0);
  float blot = valueNoise(dp) * 0.6 + valueNoise(dp * 2.3 + 4.0) * 0.4;
  float burn = smoothstep(0.58, 0.75, blot) * param[2];
  float soot = (1.0 - smoothstep(0.18, 0.32, blot)) * param[2];
  float row = floor(yy * resolution.y * 0.5);
  float scr = step(0.997 - 0.004 * param[2], hash(vec2(row, sn + fi * 13.0)));

  // Through the film: its base darkens, its frames lay the room over again, its holes, track,
  // burns and scratches let the light through.
  float base = max(cov - white - pic, 0.0);
  l *= 1.0 - a * (0.75 * base + 0.45 * soot * cov);
  l = mix(l, filmL, a * (i < 2 ? 0.8 : 0.0) * pic);
  l = mix(l, paper, clamp(a * (1.2 * white + 0.8 * burn * cov + 0.5 * scr * cov), 0.0, 1.0));
}

// The speed smears what went before: the last frame, dragged on with the heavy film.
vec3 smear = lastFrame(uv + vec2(travel0 / aspect, 0.0));
l = mix(l, dot(smear, Y), param[3] * (0.2 + 0.55 * covAll));

l = clamp(l, 0.0, 1.0);
vec3 tone = mix(palette[0], palette[1], clamp(l / 0.3, 0.0, 1.0));
tone = mix(tone, palette[2], clamp((l - 0.3) / 0.4, 0.0, 1.0));
tone = mix(tone, palette[3], clamp((l - 0.7) / 0.3, 0.0, 1.0));
return mix(under, tone, strength);
